using System.ComponentModel.DataAnnotations;

namespace backend.DTOs;

public sealed record SongCredit(
  int ContributorId,
  string ContributorName,
  string Role);

public sealed record Song(
  string SongId,
  string? YoutubeId,
  string Title,
  string? SpecialNotes,
  DateTimeOffset? ReleaseDate,
  string? ThumbnailUrl,
  IReadOnlyList<ArtistSummary> Artists,
  IReadOnlyList<SongCredit> Credits);

public sealed record SongCreditInput
{
  public required int ContributorId { get; init; }

  [Required, MaxLength(100)]
  public required string Role { get; init; }
}

// SongId is generated by the server. Artists and credits are replaced as a whole.
public sealed record SongInput
{
  [MaxLength(15)]
  public string? YoutubeId { get; init; }

  [Required, MaxLength(100)]
  public required string Title { get; init; }

  [MaxLength(1000)]
  public string? SpecialNotes { get; init; }

  public DateTimeOffset? ReleaseDate { get; init; }

  [MaxLength(500)]
  public string? ThumbnailUrl { get; init; }

  public IReadOnlyList<int> ArtistIds { get; init; } = [];

  public IReadOnlyList<SongCreditInput> Credits { get; init; } = [];
}
